sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

    var data = {};
    try {
        data = JSON.parse(event.parm2 || '{}');
    } catch (e) {
        data = {};
    }

    var panName = data.customerName || 'Customer';
    var panNumber = data.pan || '';
    var portalUrl = gs.getProperty('glide.servlet.uri') + '?id=uclm_nt_bank_guarantee_monitor';

    var html = '';
    html += '<p style="margin: 0 0 16px 0; font-size: 14px; line-height: 1.6; color: #1a1a1a;">Dear Team,</p>';
    html += '<p style="margin: 0 0 24px 0; font-size: 14px; line-height: 1.6; color: #3a4451;">';
    html += 'Please update your Credit Limit under Bank Guarantee Monitor for <strong>' + panName + '</strong>' + (panNumber ? ' (PAN: <strong>' + panNumber + '</strong>)' : '') + '.';
    html += '</p>';

    // Direct Portal Access Button
    html += '<div style="margin: 20px 0 10px 0;">';
    html += '  <a href="' + portalUrl + '" target="_blank" style="background-color: #e87722; color: #ffffff; padding: 10px 22px; text-decoration: none; border-radius: 6px; font-weight: bold; font-size: 13px; display: inline-block;">Open Bank Guarantee Monitor</a>';
    html += '</div>';

    template.print(html);

})(current, template, email, email_action, event);
